using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.Linq;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var sc = EditorSceneManager.GetActiveScene();
            if (EditorApplication.isPlaying || sc.isDirty || !sc.path.EndsWith("r102.unity"))
                throw new Exception("Clean Edit r102 required: " + sc.path + " dirty=" + sc.isDirty);
            var all = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            int missing = all.Sum(t => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            int refs = 0;
            var text = new StringBuilder("Unity=" + Application.unityVersion + " Scene=" + sc.path + " dirty=" + sc.isDirty + " Missing=" + missing + "\n");
            int interactions = s.GetComponentsInChildren<InvestigationInteractable>(true).Length;
            int oldHeads = all.Count(t => t.name == "ConRoi_Head_SameAsMinh");
            text.AppendLine("Interaction=" + interactions + " oldHeads=" + oldHeads + " explicitRequiredRefFailures=" + refs + "\ncontroller=" + s.movement.controller.stepOffset + "/" + s.movement.controller.slopeLimit + "\nMain pose refs=" + s.GetComponentsInChildren<InvestigationActor>(true).Count(a => a.head && a.leftUpper && a.rightUpper));
            if (!s.eye || !s.movement || !s.look || !s.clipCamera || !s.stageCamera || s.poseIcons.Length != 15 || s.poseIcons.Any(i => !i))
                throw new Exception("Session refs");
            foreach (var g in s.GetComponentsInChildren<ReturnGateMechanism>(true))
                if (!g.leaf || !g.latch || !g.releaseLine)
                    throw new Exception("Gate refs " + g.name);
            foreach (var mb in all.SelectMany(t => t.GetComponents<MonoBehaviour>()).Where(m => m && m.GetType().Assembly == typeof(InvestigationSession).Assembly))
                if (mb != s.movement && mb != s.look && mb.GetType().Namespace != "ConRoi.Investigation.V36")
                    throw new Exception("Legacy gameplay " + mb.GetType().Name);
            File.WriteAllText("Test/KetQua/investigation_r102/final-scene-audit.txt", text.ToString());
            if (missing != 0 || interactions != 17 || refs != 0 || oldHeads != 0)
                throw new Exception(text.ToString());
            r.Log(text.ToString());
        }
    }
}

